import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";
import { testChanges } from "./test-changes.js";  // mechanical: removed assertions, .skip/.only, @skip, longer timeouts

const SCOPE_PROMPT = `You review a pull request for scope, as a careful reviewer from another team would.
You get the ticket and the diff, nothing else. Decide whether every change serves the ticket.

Veto when you see:
- a change the ticket does not need: refactors, renames, reformatting or "while I was here" fixes in other code;
- a test made weaker: removed or loosened assertions, skipped tests, longer timeouts, fewer cases, lower thresholds.

Small supporting changes the ticket clearly needs are fine (a new test ID, a helper the fix uses, a type).
When you are unsure, say so in the note and pass. Cite the file and lines for every item.`;

const Item = z.object({ path: z.string(), lines: z.string(), why: z.string() });
export const ScopeVerdict = z.object({
  verdict: z.enum(["pass", "veto"]), unrelated: z.array(Item), weakened_tests: z.array(Item), note: z.string(),
});
export type ScopeVerdict = z.infer<typeof ScopeVerdict>;

export async function scopeJudge(ticket: string, diff: string): Promise<ScopeVerdict> {
  const prompt = `Ticket:\n${ticket}\n\nDiff:\n${diff}\n\nTest changes:\n${testChanges(diff)}`;
  for await (const msg of query({ prompt, options: {
    model: "claude-sonnet-5-5", effort: "medium", tools: [], settingSources: [],  // a rubric judge in its own session
    systemPrompt: SCOPE_PROMPT,
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(ScopeVerdict) },
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return ScopeVerdict.parse(msg.structured_output);
  }
  throw new Error("the scope judge returned no verdict");
}

import { execFile } from "node:child_process";
import { writeFile } from "node:fs/promises";
import { promisify } from "node:util";
import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";

const LENSES = "/opt/ai-agents/byte-playbooks";  // Byte's lens files, baked into the image

export const Finding = z.object({
  path: z.string(), line: z.number().int(), rule: z.string(), severity: z.enum(["important", "nit"]), body: z.string(),
});
export type Finding = z.infer<typeof Finding>;
const Findings = z.object({ findings: z.array(Finding) });

const PROMPT = `You review a change you did not write. Read the ticket, the approved plan and the diff in /run/nova/review/diff.patch.
Use the lenses in ${LENSES}. Report what matters: bugs, security problems, a requirement or plan item that is missing,
and changes the plan did not ask for. Mark each finding important or nit, with path and line.
Don't list every possible improvement. No findings is a fine answer for a clean diff.`;

export async function reviewOnce(ticket: string, planMd: string): Promise<Finding[]> {
  const { stdout } = await promisify(execFile)("git", ["diff", "origin/main...HEAD"], { cwd: "/work/fcp", maxBuffer: 64 << 20 });
  await writeFile("/run/nova/review/diff.patch", stdout);  // the harness runs git; the reviewer only reads
  const prompt = `Ticket:\n${ticket}\n\nApproved plan:\n${planMd}`;
  for await (const msg of query({ prompt, options: {
    model: "claude-opus-5-5", effort: "medium",  // logic and security, per the routing table
    cwd: "/work/fcp", settingSources: ["project"],  // repo conventions (frontend/AGENTS.md) still apply
    systemPrompt: PROMPT,
    allowedTools: ["Read", "Grep", "Glob"],  // no Bash: git diff --no-index or --output= could read or write outside the repo
    disallowedTools: ["Bash", "Edit", "Write", "NotebookEdit", "WebFetch", "WebSearch"],
    permissionMode: "dontAsk",  // anything not allowed above is refused
    additionalDirectories: [LENSES, "/run/nova/review"],
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Findings) },
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return Findings.parse(msg.structured_output).findings;
  }
  throw new Error("the reviewer returned no result");  // the harness adds fingerprints and saves to .nova/review.jsonl
}

import type { Plan } from "@rhinohealth/ai-agents-shared";
import { scopeJudge } from "./judges/scope.js";
import { fingerprinted, reviewOnce, reviewPanel, type Fingerprinted } from "./review.js";  // sha1 per finding (G4-18)
import type { NovaSession } from "./session.js";  // G3's harness session
export class Receipt {  // .nova/receipt.json (found, fixed, left) is written from it for the PR body and Byte
  found = 0;
  get fixed() { return this.fixedPrints.size; }  // each finding is fixed at most once; a return is ping-pong
  left: [finding: string, reason: string][] = [];
  fixedPrints = new Set<string>();
  leftPrints = new Set<string>();
  leave(f: Fingerprinted, reason: string) { this.left.push([`${f.path}:${f.line}`, reason]); this.leftPrints.add(f.fingerprint); }
}

export async function selfReview(session: NovaSession, plan: Plan, receipt: Receipt): Promise<Receipt> {
  while (true) {  // no round cap: it ends when nothing important is open; G3's progress watcher spots loops
    const found = plan.workflow ? await reviewPanel(session, plan) : await reviewOnce(session.ticket, session.planMd);
    const important = fingerprinted(found).filter((f) => f.severity === "important" && !receipt.leftPrints.has(f.fingerprint));
    if (!important.length) break;
    receipt.found += important.length;
    for (const f of important) {
      if (receipt.fixedPrints.has(f.fingerprint)) {  // back after a "fix": ping-pong, so a person decides
        receipt.leave(f, "it came back after a fix; asked the requester");
        await session.askHuman(`A review finding keeps coming back: ${f.path}:${f.line} ${f.body}`);
        continue;
      }
      const outcome = await session.fixOrExplain(f);  // Nova may disagree, with a reason
      if (outcome.fixed) receipt.fixedPrints.add(f.fingerprint);
      else receipt.leave(f, outcome.reason);
    }
    await session.rerunChecks();  // a fix must not break a QA check
  }
  const verdict = await scopeJudge(session.ticket, await session.diff());  // G4-17: ticket + diff only
  if (verdict.verdict === "veto") await session.handleVeto(verdict);  // revert or explain; a second veto goes to a person
  return receipt;
}

import type { Options } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";

const QA_PROMPT = `You are a careful tester. You get the QA plan and the app's URL. You do not get the code or the diff.
For each check, open a fresh browser context, do what a user would do, and look at what the screen really shows.
Pass a check only when you saw the expected result yourself. Close is not a pass: a missing state, an overlap,
a wrong count, or text that appears only after a reload is a fail. Read the calibration examples first.`;

export const QaResults = z.object({  // saved as .nova/qa_results.json
  checks: z.array(z.object({ id: z.string(), passed: z.boolean(), saw: z.string(), video: z.string() })),  // video: S3 key
});

export function qaOptions(screensAreTheJob: boolean): Options {
  return {
    model: screensAreTheJob ? "claude-opus-5-5" : "claude-sonnet-5-5",  // routing table
    effort: screensAreTheJob ? "low" : "medium",
    cwd: "/work/.nova/qa",  // the QA plan and calibration examples, not the checkout
    settingSources: [],  // no repo CLAUDE.md, skills or memory
    systemPrompt: QA_PROMPT,
    mcpServers: { playwright: {  // pinned in the image; flags per the pinned version (check --save-video)
      type: "stdio",
      command: "/opt/ai-agents/bin/playwright-mcp",
      args: ["--isolated", "--save-video=1280x720", "--output-dir=/work/.nova/qa/videos"],
    } },
    strictMcpConfig: true,
    allowedTools: ["Read", "mcp__playwright"],  // check the server-level allow rule
    disallowedTools: ["Bash", "Grep", "Glob", "Edit", "Write", "WebFetch", "WebSearch", "Read(/work/fcp/**)"],
    permissionMode: "dontAsk",
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(QaResults) },  // per check: id, passed, saw, video
  };
}
// App under test: FCP Lab on this VM, seeded with fake data via POST {API_PREFIX}test/create_test_data.
